// renderLucideIcon returns an inline SVG element for the given icon name
// or empty string if the name isn't in lucideIcons. The SVG uses
// currentColor so it inherits from the surrounding text/heading colour.
func renderLucideIcon(name string) string {
	paths, ok := lucideIcons[name]
	if !ok {
		return ""
	}
	return `<svg class="icon" viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">` + paths + `</svg>`
}
